class Command(BaseCommand):
    help = 'Import bundled Coastal Pearl menu'
    def handle(self, *args, **kwargs):
        cats = {}
        for x in MENU:
            if x['category'] not in cats:
                cats[x['category']] = len(cats)
        for name, order in cats.items():
            MenuCategory.objects.update_or_create(name=name, defaults={'active': True, 'sort_order': order})
        for i, x in enumerate(MENU):
            c = MenuCategory.objects.get(name=x['category'])
            MenuItem.objects.update_or_create(category=c, name=x['name'], defaults={'marathi_name': x['marathi_name'], 'price': x['price'], 'item_type': x['item_type'], 'available': x['available'], 'active': True, 'sort_order': i})
        self.stdout.write(self.style.SUCCESS(f'Imported {len(MENU)} menu items in {len(cats)} categories.'))
